/**
 * Python-flavoured exception types.
 *
 * Only the pieces the port actually needs are modelled: a name (used when
 * rendering a traceback) and the message that follows the colon.
 */

export class PyError extends Error {
  constructor(name, message) {
    super(message);
    this.pyName = name;
  }

  /** Mirrors how Python renders an uncaught exception's final line. */
  format() {
    return this.message === '' ? this.pyName : `${this.pyName}: ${this.message}`;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super('TypeError', message);
  }
}

