/**
 * A minimal Python value model.
 *
 * JavaScript collapses Python's `int` and `float` into one numeric type, but
 * the JSON encoder has to tell them apart (`1` vs `1.0`). The mapping used
 * throughout this port is:
 *
 *   Python str   -> JS string
 *   Python int   -> JS BigInt          (arbitrary precision, like Python)
 *   Python float -> PyFloat wrapper    (IEEE-754 double inside)
 *   Python bool  -> JS boolean
 *   Python None  -> JS null
 *   Python list  -> JS Array
 *   Python dict  -> JS Map (insertion ordered, like dict)
 */

/** Wrapper marking a double as a Python `float` rather than an `int`. */
export class PyFloat {
  constructor(value) {
    this.value = value;
  }
}

export const pyFloat = (value) => new PyFloat(value);

export const isPyFloat = (o) => o instanceof PyFloat;
export const isPyInt = (o) => typeof o === 'bigint';
export const isPyStr = (o) => typeof o === 'string';
export const isPyBool = (o) => typeof o === 'boolean';
export const isPyNone = (o) => o === null || o === undefined;
export const isPyList = (o) => Array.isArray(o);
export const isPyDict = (o) => o instanceof Map;

/** Builds a Python-style dict from `[key, value]` pairs. */
export const pyDict = (entries) => new Map(entries);

/**
 * Compares two strings the way Python's `<` does: by Unicode code point.
 *
 * JavaScript's default string ordering compares UTF-16 code units, which puts
 * astral characters (encoded as surrogate pairs starting at 0xD800) *before*
 * characters in the U+E000-U+FFFF range. Python has no such quirk.
 */
export function compareCodePoints(a, b) {
  if (a === b) return 0;
  const left = Array.from(a);
  const right = Array.from(b);
  const shared = Math.min(left.length, right.length);
  for (let i = 0; i < shared; i++) {
    const x = left[i].codePointAt(0);
    const y = right[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}

/** `sorted(dct.items())` for dicts whose keys are all strings. */
export function sortedItems(dict) {
  return [...dict.entries()].sort((x, y) => compareCodePoints(x[0], y[0]));
}

