/**
 * `repr()` for Python floats.
 *
 * CPython formats a float with the 'r' (repr) mode of `PyOS_double_to_string`:
 * take the shortest digit string that round-trips, then choose between fixed
 * and exponential notation based on the decimal point position.
 */

/**
 * Decomposes a finite, non-zero-signed magnitude into its shortest
 * round-tripping digits and the position of the decimal point.
 *
 * `Number.prototype.toExponential()` called without an argument is specified to
 * use "as many digits as necessary to uniquely specify the number", i.e. the
 * same shortest representation CPython's dtoa produces.
 *
 * @returns {{digits: string, decpt: number}} `0.digits * 10**decpt == value`
 */
function shortestDigits(magnitude) {
  const [mantissa, exponent] = magnitude.toExponential().split('e');
  const digits = mantissa.replace('.', '');
  // toExponential normalises to one digit before the point, so the decimal
  // point sits one place to the right of that digit.
  return { digits, decpt: Number(exponent) + 1 };
}

/** Formats the exponent suffix: always signed, always at least two digits. */
function exponentSuffix(exp) {
  const sign = exp < 0 ? '-' : '+';
  return `e${sign}${String(Math.abs(exp)).padStart(2, '0')}`;
}

/**
 * Renders a double exactly as Python's `repr(float)` / `str(float)` would.
 *
 *   1.0                 -> "1.0"      (integral values keep a trailing ".0")
 *   1e15                -> "1000000000000000.0"
 *   1e16                -> "1e+16"    (switches to exponential at decpt > 16)
 *   0.0001              -> "0.0001"
 *   0.00001             -> "1e-05"    (switches to exponential at decpt <= -4)
 *   -0.0                -> "-0.0"
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  // Object.is distinguishes -0.0 from 0.0, which `value < 0` cannot.
  const negative = value < 0 || Object.is(value, -0);
  const { digits, decpt } = shortestDigits(Math.abs(value));

  let body;
  if (decpt <= -4 || decpt > 16) {
    const tail = digits.length > 1 ? `.${digits.slice(1)}` : '';
    body = `${digits[0]}${tail}${exponentSuffix(decpt - 1)}`;
  } else if (decpt <= 0) {
    body = `0.${'0'.repeat(-decpt)}${digits}`;
  } else if (decpt >= digits.length) {
    body = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  } else {
    body = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
  }

  return negative ? `-${body}` : body;
}

/** `repr()` for Python ints, which this port models as BigInt. */
export function intRepr(value) {
  return value.toString();
}

