/**
 * `repr()` for Python `bytes` objects.
 *
 * This is what `print(b"...")` actually shows, and the program under port
 * prints two bytes objects, so the escaping rules matter character for
 * character.
 */

const BACKSLASH = 0x5c;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;
const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SPACE = 0x20;
const DEL = 0x7f;

const HEX = '0123456789abcdef';

/**
 * Renders a byte string the way CPython's `bytes_repr` does.
 *
 * Quote selection: single quotes, unless the payload contains a single quote
 * and no double quote (then double quotes are used so nothing needs escaping).
 * Bytes below 0x20 and at or above 0x7f become `\xHH` with lowercase hex,
 * except for the three that have short forms (`\t`, `\n`, `\r`).
 */
export function bytesRepr(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (const byte of bytes) {
    if (byte === SINGLE_QUOTE) hasSingle = true;
    else if (byte === DOUBLE_QUOTE) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
  const quoteChar = String.fromCharCode(quote);

  let out = `b${quoteChar}`;
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) {
      out += `\\${String.fromCharCode(byte)}`;
    } else if (byte === TAB) {
      out += '\\t';
    } else if (byte === NEWLINE) {
      out += '\\n';
    } else if (byte === CARRIAGE_RETURN) {
      out += '\\r';
    } else if (byte < SPACE || byte >= DEL) {
      out += `\\x${HEX[byte >> 4]}${HEX[byte & 0xf]}`;
    } else {
      out += String.fromCharCode(byte);
    }
  }
  return out + quoteChar;
}

