/**
 * UTF-8 codec.
 *
 * Written by hand rather than reaching for TextEncoder so the surrogate
 * handling can match Python's: `str.encode("utf-8")` refuses lone surrogates
 * instead of substituting U+FFFD.
 */

import { PyError } from '../errors.mjs';

class PyUnicodeEncodeError extends PyError {
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

/**
 * Encodes a string to UTF-8 bytes.
 *
 * @param {string} text
 * @returns {Uint8Array}
 */
export function encodeUtf8(text) {
  const out = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);

    if (cp >= 0xd800 && cp <= 0xdbff) {
      const low = text.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        cp = (cp - 0xd800) * 0x400 + (low - 0xdc00) + 0x10000;
        i++;
      } else {
        throw new PyUnicodeEncodeError(
          `'utf-8' codec can't encode character '\\u${cp.toString(16)}' ` +
            `in position ${i}: surrogates not allowed`,
        );
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      throw new PyUnicodeEncodeError(
        `'utf-8' codec can't encode character '\\u${cp.toString(16)}' ` +
          `in position ${i}: surrogates not allowed`,
      );
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return Uint8Array.from(out);
}

