/**
 * Unicode pre-processing shared by Python's `int()` and `float()` string
 * constructors.
 *
 * Before parsing, CPython runs the input through
 * `_PyUnicode_TransformDecimalAndSpaceToASCII`, which maps any character with
 * the Unicode decimal-digit property to its ASCII equivalent and any Unicode
 * whitespace character to a plain space. That is why `int('١٢')` returns 12.
 */

/**
 * Code points of the character that means "zero" in each contiguous run of ten
 * Unicode decimal digits (general category Nd). Derived by enumerating `\p{Nd}`
 * and slicing each run into groups of ten.
 */
const DIGIT_ZEROS = [
  0x30, 0x660, 0x6f0, 0x7c0, 0x966, 0x9e6, 0xa66, 0xae6, 0xb66, 0xbe6, 0xc66,
  0xce6, 0xd66, 0xde6, 0xe50, 0xed0, 0xf20, 0x1040, 0x1090, 0x17e0, 0x1810,
  0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0, 0x1c40, 0x1c50, 0xa620,
  0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0, 0xff10, 0x104a0, 0x10d30,
  0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0, 0x11450, 0x114d0, 0x11650,
  0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50, 0x11d50, 0x11da0, 0x11f50,
  0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1d7d8, 0x1d7e2, 0x1d7ec, 0x1d7f6,
  0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950, 0x1fbf0,
];

/** Characters for which CPython's `Py_UNICODE_ISSPACE` is true. */
const PY_SPACE = new Set(
  [
    0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0,
    0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
    0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
  ].map((cp) => String.fromCodePoint(cp)),
);

/** True when `ch` is whitespace by Python's definition. */
export const isPySpace = (ch) => PY_SPACE.has(ch);

/** Returns the 0-9 value of a Unicode decimal digit, or -1 if it is not one. */
function decimalValue(cp) {
  for (const zero of DIGIT_ZEROS) {
    const offset = cp - zero;
    if (offset >= 0 && offset <= 9) return offset;
  }
  return -1;
}

/**
 * Folds Unicode digits to ASCII digits and Unicode whitespace to U+0020.
 *
 * Characters that are neither are passed through unchanged; the caller's
 * grammar check is what ultimately rejects them.
 */
export function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      out += ch;
      continue;
    }
    if (PY_SPACE.has(ch)) {
      out += ' ';
      continue;
    }
    const value = decimalValue(cp);
    out += value >= 0 ? String(value) : ch;
  }
  return out;
}

/** Python's `str.strip()` with no argument. */
export function pyStrip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isPySpace(text[start])) start++;
  while (end > start && isPySpace(text[end - 1])) end--;
  return text.slice(start, end);
}

