/**
 * Ports of Python's `int(str)` and `float(str)` constructors, including the
 * details argparse leans on: surrounding whitespace is ignored, an explicit
 * sign is allowed, and PEP 515 underscores may separate digits.
 */

import { PyValueError } from '../errors.mjs';
import { pyStrip, transformDecimalAndSpaceToAscii } from './unicodedigits.mjs';
import { strRepr } from '../repr/strrepr.mjs';

/** One or more digits, optionally separated by single underscores. */
const DIGITS = String.raw`\d(?:_?\d)*`;

const INT_RE = new RegExp(String.raw`^[+-]?${DIGITS}$`);

const FLOAT_RE = new RegExp(
  String.raw`^[+-]?(?:${DIGITS}(?:\.(?:${DIGITS})?)?|\.${DIGITS})` +
    String.raw`(?:[eE][+-]?${DIGITS})?$`,
);

const INFINITY_RE = /^[+-]?(?:inf|infinity)$/i;
const NAN_RE = /^[+-]?nan$/i;

/**
 * `int(text)` — returns a BigInt so arbitrary precision is preserved.
 *
 * @throws {PyValueError} with CPython's exact message on bad input.
 */
export function pyInt(text) {
  const cleaned = pyStrip(transformDecimalAndSpaceToAscii(text));
  if (!INT_RE.test(cleaned)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${strRepr(text)}`,
    );
  }
  return BigInt(cleaned.replace(/_/g, ''));
}

/**
 * `float(text)` — returns a plain JS number.
 *
 * `Number()` performs the same correctly-rounded decimal-to-double conversion
 * as CPython's `strtod`, so once the grammar has been validated and the
 * underscores stripped the two agree bit for bit.
 *
 * @throws {PyValueError} with CPython's exact message on bad input.
 */
export function pyFloatFromString(text) {
  const cleaned = pyStrip(transformDecimalAndSpaceToAscii(text));

  if (INFINITY_RE.test(cleaned)) {
    return cleaned[0] === '-' ? -Infinity : Infinity;
  }
  if (NAN_RE.test(cleaned)) {
    return NaN;
  }
  if (!FLOAT_RE.test(cleaned)) {
    throw new PyValueError(`could not convert string to float: ${strRepr(text)}`);
  }
  return Number(cleaned.replace(/_/g, ''));
}

