/**
 * JSON string escaping, matching the two modes of CPython's `json` module.
 */

const ESCAPE_DCT = new Map([
  ['\\', '\\\\'],
  ['"', '\\"'],
  ['\b', '\\b'],
  ['\f', '\\f'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

// Every remaining C0 control character gets a \u00XX escape.
for (let i = 0; i < 0x20; i++) {
  const ch = String.fromCharCode(i);
  if (!ESCAPE_DCT.has(ch)) {
    ESCAPE_DCT.set(ch, `\\u${i.toString(16).padStart(4, '0')}`);
  }
}

const NEEDS_ESCAPE = /[\x00-\x1f\\"]/;

/**
 * `ensure_ascii=False` escaping: only the control characters, the backslash
 * and the double quote are escaped. Everything else — including DEL, U+2028
 * and every non-ASCII character — is emitted verbatim.
 */
export function encodeBasestring(text) {
  if (!NEEDS_ESCAPE.test(text)) return `"${text}"`;

  let out = '"';
  for (const ch of text) {
    const escaped = ESCAPE_DCT.get(ch);
    out += escaped === undefined ? ch : escaped;
  }
  return out + '"';
}

/**
 * `ensure_ascii=True` escaping: as above, plus a `\uXXXX` escape for every
 * character outside printable ASCII, with surrogate pairs kept as two escapes.
 */
export function encodeBasestringAscii(text) {
  let out = '"';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const escaped = ESCAPE_DCT.get(ch);
    if (escaped !== undefined) {
      out += escaped;
      continue;
    }
    const code = text.charCodeAt(i);
    if (code >= 0x20 && code < 0x7f) {
      out += ch;
    } else {
      out += `\\u${code.toString(16).padStart(4, '0')}`;
    }
  }
  return out + '"';
}

