/**
 * canonicaljson — the three entry points the program under port uses.
 *
 * Canonical form is JSON with keys sorted, no insignificant whitespace, no
 * `\uXXXX` escaping of non-ASCII characters, and UTF-8 bytes as the result.
 */

import { encodeUtf8 } from '../codecs/utf8.mjs';
import { JSONEncoder } from '../json/encoder.mjs';

const canonicalEncoder = new JSONEncoder({
  ensureAscii: false,
  allowNan: false,
  sortKeys: true,
  separators: [',', ':'],
});

const prettyEncoder = new JSONEncoder({
  ensureAscii: false,
  allowNan: false,
  sortKeys: true,
  indent: 4,
  separators: [',', ': '],
});

/**
 * `canonicaljson.encode_canonical_json`
 *
 * @returns {Uint8Array} UTF-8 bytes of the canonical encoding.
 */
export function encodeCanonicalJson(obj) {
  return encodeUtf8(canonicalEncoder.encode(obj));
}

/**
 * `canonicaljson.encode_pretty_printed_json`
 *
 * @returns {Uint8Array} UTF-8 bytes of the four-space-indented encoding.
 */
export function encodePrettyPrintedJson(obj) {
  return encodeUtf8(prettyEncoder.encode(obj));
}

/**
 * `canonicaljson.iterencode_canonical_json`
 *
 * Yields the canonical encoding piecewise; each string chunk from the
 * underlying encoder becomes one UTF-8 byte chunk.
 *
 * @returns {Generator<Uint8Array>}
 */
export function* iterencodeCanonicalJson(obj) {
  for (const chunk of canonicalEncoder.iterencode(obj)) {
    yield encodeUtf8(chunk);
  }
}

