/**
 * Blocking stdio helpers.
 *
 * Node buffers writes to pipes asynchronously, which means `process.exit()`
 * can drop output that has not been flushed. Writing through `fs.writeSync`
 * keeps the ordering and completeness guarantees Python's `print` has.
 */

import { writeSync } from 'node:fs';

import { encodeUtf8 } from '../codecs/utf8.mjs';

const STDOUT = 1;
const STDERR = 2;

function writeAll(fd, bytes) {
  let offset = 0;
  while (offset < bytes.length) {
    try {
      offset += writeSync(fd, bytes, offset, bytes.length - offset);
    } catch (err) {
      // Non-blocking pipes surface EAGAIN; retrying is the correct response.
      if (err.code === 'EAGAIN') continue;
      // A closed reader is not an error worth crashing over, as in Python.
      if (err.code === 'EPIPE') return;
      throw err;
    }
  }
}

/** `print(text)` — appends the trailing newline. */
export function printLine(text) {
  writeAll(STDOUT, encodeUtf8(`${text}\n`));
}

/** Writes to stdout with no newline added, like `sys.stdout.write`. */
export function writeStdout(text) {
  writeAll(STDOUT, encodeUtf8(text));
}

/** Writes to stderr with no newline added, like `sys.stderr.write`. */
export function writeStderr(text) {
  writeAll(STDERR, encodeUtf8(text));
}

