/**
 * A port of argparse's `HelpFormatter`, covering the layout rules that decide
 * where help text starts, how the usage line wraps, and how sections nest.
 */

const MAX_HELP_POSITION = 24;
const INDENT_INCREMENT = 2;

/**
 * Terminal width the way `shutil.get_terminal_size()` computes it: the COLUMNS
 * environment variable wins, then the real terminal, then an 80-column
 * fallback. argparse then subtracts two.
 */
export function terminalWidth() {
  const columns = process.env.COLUMNS;
  if (columns) {
    const parsed = Number.parseInt(columns, 10);
    if (Number.isFinite(parsed) && parsed > 0) return parsed - 2;
  }
  if (process.stdout.isTTY && process.stdout.columns) {
    return process.stdout.columns - 2;
  }
  return 80 - 2;
}

/** `'--a A'` / `'-h, --help'` — how an action is introduced in the help body. */
export function formatActionInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((opt) => `${opt} ${action.metavar}`).join(', ');
}

/** `'[-h]'` / `'--a A'` — how an action appears inside the usage line. */
function formatActionUsage(action) {
  const opt = action.optionStrings[0];
  const part = action.nargs === 0 ? opt : `${opt} ${action.metavar}`;
  return action.required ? part : `[${part}]`;
}

/**
 * Greedily packs usage fragments into lines, mirroring argparse's inner
 * `get_lines` helper (including the way the first line drops the indent when a
 * prefix was supplied).
 */
function getLines(parts, indent, textWidth, prefix = null) {
  const lines = [];
  let line = [];
  let lineLen = (prefix !== null ? prefix.length : indent.length) - 1;

  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** Builds the `usage: ...` block, wrapping it if it overflows the terminal. */
export function formatUsage(prog, actions, width) {
  const prefix = 'usage: ';
  const optParts = actions.map(formatActionUsage);
  let usage = [prog, ...optParts].join(' ');

  if (prefix.length + usage.length > width) {
    if (prefix.length + prog.length <= 0.75 * width) {
      const indent = ' '.repeat(prefix.length + prog.length + 1);
      usage = getLines([prog, ...optParts], indent, width, prefix).join('\n');
    } else {
      const indent = ' '.repeat(prefix.length);
      usage = [prog, ...getLines(optParts, indent, width)].join('\n');
    }
  }
  return `${prefix}${usage}\n\n`;
}

/**
 * Renders the `options:` section.
 *
 * The help column starts at `min(longest_invocation + 2 + 2, 24)`; an action
 * whose invocation would overflow that column puts its help on the next line.
 */
export function formatSection(title, actions, width) {
  const actionMaxLength = Math.max(
    0,
    ...actions.map((a) => formatActionInvocation(a).length + INDENT_INCREMENT),
  );
  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
  const helpWidth = Math.max(width - helpPosition, 11);
  const actionWidth = helpPosition - INDENT_INCREMENT - 2;

  let body = '';
  for (const action of actions) {
    const invocation = formatActionInvocation(action);
    const pad = ' '.repeat(INDENT_INCREMENT);

    if (!action.help) {
      body += `${pad}${invocation}\n`;
      continue;
    }

    let header;
    let indentFirst;
    if (invocation.length <= actionWidth) {
      header = `${pad}${invocation.padEnd(actionWidth)}  `;
      indentFirst = 0;
    } else {
      header = `${pad}${invocation}\n`;
      indentFirst = helpPosition;
    }

    const helpLines = wrapText(action.help, helpWidth);
    body += header;
    body += `${' '.repeat(indentFirst)}${helpLines[0]}\n`;
    for (const line of helpLines.slice(1)) {
      body += `${' '.repeat(helpPosition)}${line}\n`;
    }
  }

  return body === '' ? '' : `${title}:\n${body}\n`;
}

/** `textwrap.wrap` on whitespace-collapsed text, which is all argparse needs. */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [''];

  const lines = [];
  let line = words[0];
  for (const word of words.slice(1)) {
    if (line.length + 1 + word.length > width) {
      lines.push(line);
      line = word;
    } else {
      line += ` ${word}`;
    }
  }
  lines.push(line);
  return lines;
}

