/**
 * Renders an uncaught Python exception the way the frozen executable does: a
 * CPython traceback followed by PyInstaller's bootloader complaint.
 *
 * The frames are fixed because there is exactly one place in this program that
 * can raise — `encode_canonical_json` on line 18 of the script — and the two
 * reachable failures (a non-finite float, and a string that is not encodable
 * as UTF-8) each stop at a known depth inside the library.
 */

const SCRIPT_FRAMES = [
  '  File "test10.py", line 26, in <module>',
  '  File "test10.py", line 18, in main',
];

/** Frames for `ValueError`, raised while the encoder walks the object. */
const ENCODE_FRAMES = [
  '  File "canonicaljson/__init__.py", line 84, in encode_canonical_json',
  '  File "json/encoder.py", line 200, in encode',
  '  File "json/encoder.py", line 258, in iterencode',
];

/** Frames for a UTF-8 failure, which happens one line later, on `.encode()`. */
const UTF8_FRAMES = [
  '  File "canonicaljson/__init__.py", line 85, in encode_canonical_json',
];

export function formatTraceback(error) {
  const inner = error.pyName === 'UnicodeEncodeError' ? UTF8_FRAMES : ENCODE_FRAMES;
  const lines = [
    'Traceback (most recent call last):',
    ...SCRIPT_FRAMES,
    ...inner,
    error.format(),
  ];
  return `${lines.join('\n')}\n`;
}

/** The line PyInstaller's bootloader prints after a script dies. */
export function formatBootloaderError(scriptName) {
  return (
    `[PYI-${process.pid}:ERROR] Failed to execute script ` +
    `'${scriptName}' due to unhandled exception!\n`
  );
}

