#!/usr/bin/env node
/**
 * Node.js port of test10.py.
 *
 * Builds a small dict from three command-line values and prints its canonical
 * JSON encoding, its pretty-printed encoding, and the number of chunks the
 * iterative canonical encoder produces.
 */

import {
  encodeCanonicalJson,
  encodePrettyPrintedJson,
  iterencodeCanonicalJson,
} from './lib/canonicaljson/index.mjs';
import { ArgumentParser, SystemExit, types } from './lib/cli/argparse.mjs';
import { PyError } from './lib/errors.mjs';
import { pyDict } from './lib/pytypes.mjs';
import { bytesRepr } from './lib/repr/bytesrepr.mjs';
import { printLine, writeStderr } from './lib/sys/stdio.mjs';
import { formatBootloaderError, formatTraceback } from './lib/sys/traceback.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument(['--a'], { type: types.str, required: true });
  parser.addArgument(['--b'], { type: types.int, required: true });
  parser.addArgument(['--c'], { type: types.float, required: true });
  const args = parser.parseArgs();

  const data = pyDict([
    ['string', args.a],
    ['integer', args.b],
    ['float', args.c],
    ['list', [args.a, args.b, args.c]],
  ]);

  const canonicalResult = encodeCanonicalJson(data); // Encode as canonical JSON
  const prettyResult = encodePrettyPrintedJson(data); // Encode as pretty printed JSON
  const canonicalChunks = [...iterencodeCanonicalJson(data)]; // Get chunks from iterative encoding

  printLine(bytesRepr(canonicalResult));
  printLine(bytesRepr(prettyResult));
  printLine(String(canonicalChunks.length));
}

try {
  main();
} catch (err) {
  if (err instanceof SystemExit) {
    process.exit(err.code);
  }
  if (err instanceof PyError) {
    writeStderr(formatTraceback(err));
    writeStderr(formatBootloaderError('test10'));
    process.exit(1);
  }
  throw err;
}

