parseKnownArgs(argv) {
  const [pattern, optionTuples] = this._classify(argv);

  const namespace = {};
  const seen = new Set();
  const extras = [];
  let i = 0;

  while (i < argv.length) {
    const tuple = pattern[i] === 'O' ? optionTuples[i] : null;

    // Values, separators and unrecognised flags are all leftovers here:
    // the parser defines no positionals to absorb them.
    if (tuple === null || tuple.action === null) {
      extras.push(argv[i]);
      i++;
      continue;
    }

    const { action, explicitArg } = tuple;
    i++;

    if (action.isHelp) {
      this.printHelp();
      throw new SystemExit(0);
    }

    let raw;
    if (explicitArg !== null) {
      raw = explicitArg;
    } else {
      // Only a token classified as a plain value can serve as the argument.
      if (i >= argv.length || pattern[i] !== 'A') {
        this.error(`argument ${actionName(action)}: expected one argument`);
      }
      raw = argv[i];
      i++;
    }

    namespace[action.dest] = this._getValue(action, raw);
    seen.add(action.dest);
  }

  // argparse checks required arguments before complaining about leftovers.
  const missing = this.actions
    .filter((action) => action.required && !seen.has(action.dest))
    .map(actionName);
  if (missing.length > 0) {
    this.error(`the following arguments are required: ${missing.join(', ')}`);
  }

  return [namespace, extras];
}

/**
 * argparse's `arg_strings_pattern`: labels every token as an option (`O`), a
 * plain value (`A`), or the `--` separator (`-`). Everything following the
 * first `--` is forced to `A`, and the separator itself is never a value.
 *
 * @returns {[string[], Array<object|null>]} labels and the resolved option
 *   match for each `O` position.
 */
_classify(argv) {
  const pattern = new Array(argv.length);
  const optionTuples = new Array(argv.length).fill(null);
  let afterSeparator = false;

  for (let i = 0; i < argv.length; i++) {
    if (afterSeparator) {
      pattern[i] = 'A';
      continue;
    }
    if (argv[i] === '--') {
      afterSeparator = true;
      pattern[i] = '-';
      continue;
    }

    const tuple = this._parseOptional(argv[i]);
    if (tuple === null) {
      pattern[i] = 'A';
    } else {
      pattern[i] = 'O';
      optionTuples[i] = tuple;
    }
  }

  return [pattern, optionTuples];
}

