/**
 * A port of the slice of `argparse` this program needs: long options that take
 * exactly one value, prefix abbreviation, `--opt=value`, `--`, type conversion
 * with argparse's error wording, and the required/unrecognized checks in the
 * order argparse performs them.
 */

import { basename } from 'node:path';

import { PyError } from '../errors.mjs';
import { pyInt, pyFloatFromString } from '../parse/numeric.mjs';
import { pyFloat } from '../pytypes.mjs';
import { strRepr } from '../repr/strrepr.mjs';
import { writeStderr, writeStdout } from '../sys/stdio.mjs';
import { formatSection, formatUsage, terminalWidth } from './formatter.mjs';

/** Thrown instead of exiting inline, so the entry point owns the exit. */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}

/**
 * argparse's `_negative_number_matcher`. A token matching this is treated as a
 * value rather than an option, which is what lets `--b -42` work while
 * `--c -1e5` fails with "expected one argument".
 */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Type descriptors: the callable plus the `__name__` argparse reports. */
export const types = {
  str: { name: 'str', fn: (value) => value },
  int: { name: 'int', fn: pyInt },
  float: { name: 'float', fn: (value) => pyFloat(pyFloatFromString(value)) },
};

export class ArgumentParser {
  constructor({ prog = null } = {}) {
    this.prog = prog ?? basename(process.argv[1] ?? '');
    this.width = terminalWidth();
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      nargs: 0,
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  addArgument(
    flags,
    { type = types.str, required = false, help = null, nargs = 1, isHelp = false, metavar = null } = {},
  ) {
    const longest = flags.find((flag) => flag.startsWith('--')) ?? flags[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');

    const action = {
      optionStrings: flags,
      dest,
      type,
      required,
      help,
      nargs,
      isHelp,
      metavar: metavar ?? dest.toUpperCase(),
    };

    this.actions.push(action);
    for (const flag of flags) this.optionStringActions.set(flag, action);
    return action;
  }

  // ---------------------------------------------------------------- output

  formatUsage() {
    return formatUsage(this.prog, this.actions, this.width).replace(/\n+$/, '') + '\n';
  }

  formatHelp() {
    let help = formatUsage(this.prog, this.actions, this.width);
    help += formatSection('options', this.actions, this.width);
    help = help.replace(/\n\n\n+/g, '\n\n');
    return help.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** Writes usage plus the message to stderr and exits with status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  // --------------------------------------------------------------- parsing

  parseArgs(argv = process.argv.slice(2)) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    const namespace = {};
    const seen = new Set();
    const extras = [];
    let onlyPositional = false;
    let i = 0;

    while (i < argv.length) {
      const arg = argv[i];

      if (onlyPositional) {
        extras.push(arg);
        i++;
        continue;
      }
      if (arg === '--') {
        onlyPositional = true;
        i++;
        continue;
      }

      const parsed = this._parseOptional(arg);
      // Either a plain value or an unknown flag: both end up as leftovers.
      if (parsed === null || parsed.action === null) {
        extras.push(arg);
        i++;
        continue;
      }

      const { action, optionString, explicitArg } = parsed;
      i++;

      if (action.isHelp) {
        this.printHelp();
        throw new SystemExit(0);
      }

      let raw;
      if (explicitArg !== null) {
        raw = explicitArg;
      } else {
        const next = i < argv.length ? argv[i] : undefined;
        // A following token that itself parses as an option cannot be a value.
        if (next === undefined || this._parseOptional(next) !== null) {
          this.error(`argument ${actionName(action)}: expected one argument`);
        }
        raw = next;
        i++;
      }

      namespace[action.dest] = this._getValue(action, raw);
      seen.add(action.dest);
    }

    // argparse checks required arguments before complaining about leftovers.
    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map(actionName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * argparse's `_parse_optional`.
   *
   * @returns {null} when the token is a value, otherwise a match whose
   *   `action` is null for an unrecognised flag.
   */
  _parseOptional(argString) {
    if (!argString) return null;
    if (argString[0] !== '-') return null;

    const exact = this.optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const action = this.optionStringActions.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArg: argString.slice(eq + 1) };
      }
    }

    const candidates = this._getOptionTuples(argString);
    if (candidates.length > 1) {
      const options = candidates.map((c) => c.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    } else if (candidates.length === 1) {
      return candidates[0];
    }

    // No option looks like a negative number here, so numeric tokens are data.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** argparse's `_get_option_tuples` — abbreviation matching. */
  _getOptionTuples(optionString) {
    const result = [];

    if (optionString.startsWith('--')) {
      const eq = optionString.indexOf('=');
      const prefix = eq === -1 ? optionString : optionString.slice(0, eq);
      const explicitArg = eq === -1 ? null : optionString.slice(eq + 1);

      for (const [option, action] of this.optionStringActions) {
        if (option.startsWith(prefix)) {
          result.push({ action, optionString: option, explicitArg });
        }
      }
    } else {
      const shortPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);

      for (const [option, action] of this.optionStringActions) {
        if (option === shortPrefix) {
          result.push({ action, optionString: option, explicitArg: shortExplicitArg });
        } else if (option.startsWith(optionString)) {
          result.push({ action, optionString: option, explicitArg: null });
        }
      }
    }

    return result;
  }

  /** Runs the action's `type` callable, translating ValueError as argparse does. */
  _getValue(action, argString) {
    try {
      return action.type.fn(argString);
    } catch (err) {
      if (err instanceof PyError && err.pyName === 'ValueError') {
        this.error(
          `argument ${actionName(action)}: invalid ${action.type.name} value: ` +
            strRepr(argString),
        );
      }
      throw err;
    }
  }
}

/** argparse's `_get_action_name` for optionals. */
function actionName(action) {
  return action.optionStrings.join('/');
}

