#!/usr/bin/env node
/**
 * Randomized differential fuzzing across the three argument types.
 */

import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test10_executable';
const PORT = '/output/test10.mjs';
const ROUNDS = Number(process.argv[2] ?? 300);

const ALPHABET = [
  'a', 'Z', '0', ' ', '"', "'", '\\', '/', '\t', '\n', '\r', '\b', '\f',
  '\x01', '\x1f', '\x7f', '~', '{', '}', '[', ']', ':', ',', '测', 'é', 'ß',
  '😀', ' ', ' ', '￿', '', 'ﬀ', '?', '-', '+', '.', 'e',
];

const randInt = (n) => Math.floor(Math.random() * n);
const pick = (xs) => xs[randInt(xs.length)];

function randomString() {
  const len = randInt(12);
  let out = '';
  for (let i = 0; i < len; i++) out += pick(ALPHABET);
  // spawnSync cannot pass NUL bytes through argv, and neither can execve.
  return out.replaceAll('\0', '');
}

function randomIntArg() {
  switch (randInt(6)) {
    case 0: return String(randInt(2 ** 31) - 2 ** 30);
    case 1: return String(BigInt(randInt(1e9)) * 10n ** BigInt(randInt(30)));
    case 2: return `-${randInt(1e6)}`;
    case 3: return `${pick(['', '+', '-'])}${randInt(1000)}`;
    case 4: return `  ${randInt(1000)}  `;
    default: return randomString();
  }
}

function randomFloatArg() {
  switch (randInt(8)) {
    case 0: return String(Math.random() * 10 ** (randInt(40) - 20));
    case 1: return String(-Math.random() * 10 ** (randInt(40) - 20));
    case 2: return String(randInt(1e6));
    case 3: return `${randInt(1000)}.${randInt(1e9)}`;
    case 4: return `${randInt(10)}e${pick(['', '-', '+'])}${randInt(320)}`;
    case 5: {
      // Exercise the full double range via a random bit pattern.
      const buf = new DataView(new ArrayBuffer(8));
      buf.setUint32(0, randInt(2 ** 32) >>> 0);
      buf.setUint32(4, randInt(2 ** 32) >>> 0);
      return String(buf.getFloat64(0));
    }
    case 6: return pick(['inf', '-inf', 'nan', 'Infinity', '1e400', '5e-324']);
    default: return randomString();
  }
}

const normalise = (buf) =>
  buf
    .toString('binary')
    .replaceAll('test10_executable', 'test10.mjs')
    .replace(/\[PYI-\d+:/g, '[PYI-N:');

let failures = 0;

for (let round = 0; round < ROUNDS; round++) {
  const argv = [
    '--a', randomString(),
    '--b', randomIntArg(),
    '--c', randomFloatArg(),
  ];

  const expected = spawnSync(REFERENCE, argv, { encoding: 'buffer' });
  const actual = spawnSync('node', [PORT, ...argv], { encoding: 'buffer' });

  const mismatch =
    normalise(expected.stdout) !== normalise(actual.stdout) ||
    normalise(expected.stderr) !== normalise(actual.stderr) ||
    expected.status !== actual.status;

  if (mismatch) {
    failures++;
    console.log(`FAIL ${JSON.stringify(argv)}`);
    console.log(`  exp out ${JSON.stringify(normalise(expected.stdout))}`);
    console.log(`  got out ${JSON.stringify(normalise(actual.stdout))}`);
    console.log(`  exp err ${JSON.stringify(normalise(expected.stderr))}`);
    console.log(`  got err ${JSON.stringify(normalise(actual.stderr))}`);
    console.log(`  status exp=${expected.status} got=${actual.status}`);
    if (failures > 5) break;
  }
}

console.log(`\n${ROUNDS - failures}/${ROUNDS} fuzz rounds match`);
process.exit(failures === 0 ? 0 : 1);

