/**
 * `repr()` for Python `str`.
 *
 * Used only for the quoted values inside argparse's error messages, so the
 * ASCII rules are what matter in practice; non-ASCII printable characters are
 * emitted verbatim, matching Python for everything outside the obscure
 * unprintable categories.
 */

const HEX = '0123456789abcdef';

const shortEscapes = new Map([
  ['\\', '\\\\'],
  ['\t', '\\t'],
  ['\n', '\\n'],
  ['\r', '\\r'],
]);

/** True for the code points Python renders as `\xHH` / `\uXXXX` escapes. */
function isUnprintable(cp) {
  // C0 controls, DEL and the C1 block.
  if (cp < 0x20 || (cp >= 0x7f && cp <= 0xa0)) return true;
  // Surrogates and the soft hyphen, the other cases reachable from a CLI.
  if (cp === 0xad) return true;
  return cp >= 0xd800 && cp <= 0xdfff;
}

function escapeCodePoint(cp) {
  if (cp <= 0xff) return `\\x${HEX[cp >> 4]}${HEX[cp & 0xf]}`;
  if (cp <= 0xffff) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/**
 * Renders a string the way CPython's `unicode_repr` does: single quotes unless
 * the value contains a single quote and no double quote.
 */
export function strRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of text) {
    if (ch === quote) {
      out += `\\${ch}`;
      continue;
    }
    const short = shortEscapes.get(ch);
    if (short !== undefined) {
      out += short;
      continue;
    }
    const cp = ch.codePointAt(0);
    out += isUnprintable(cp) ? escapeCodePoint(cp) : ch;
  }
  return out + quote;
}

