/**
 * A port of CPython's `json.JSONEncoder`.
 *
 * The chunk boundaries of `iterencode` are part of the observable behaviour
 * here (the program prints how many chunks come back), so this follows
 * `json/encoder.py`'s `_make_iterencode` closely — in particular the way
 * `_iterencode_list` prepends the pending separator to the *next* value rather
 * than yielding it on its own, while `_iterencode_dict` yields key, separator
 * and value as three chunks.
 */

import { PyTypeError, PyValueError } from '../errors.mjs';
import { PyFloat } from '../pytypes.mjs';
import { compareCodePoints } from '../pytypes.mjs';
import { floatRepr, intRepr } from '../repr/floatrepr.mjs';
import { encodeBasestring, encodeBasestringAscii } from './strings.mjs';

export class JSONEncoder {
  constructor({
    skipkeys = false,
    ensureAscii = true,
    checkCircular = true,
    allowNan = true,
    sortKeys = false,
    indent = null,
    separators = null,
  } = {}) {
    this.skipkeys = skipkeys;
    this.ensureAscii = ensureAscii;
    this.checkCircular = checkCircular;
    this.allowNan = allowNan;
    this.sortKeys = sortKeys;
    this.indent = typeof indent === 'number' ? ' '.repeat(indent) : indent;

    this.itemSeparator = ', ';
    this.keySeparator = ': ';
    if (separators !== null) {
      [this.itemSeparator, this.keySeparator] = separators;
    } else if (indent !== null) {
      this.itemSeparator = ',';
    }

    this.encodeString = ensureAscii ? encodeBasestringAscii : encodeBasestring;
  }

  /** `json.JSONEncoder.encode` — the one-shot form. */
  encode(o) {
    if (typeof o === 'string') return this.encodeString(o);
    return [...this.iterencode(o)].join('');
  }

  /** `json.JSONEncoder.iterencode` — yields the document in pieces. */
  *iterencode(o) {
    const markers = this.checkCircular ? new Set() : null;
    yield* this._iterencode(o, 0, markers);
  }

  /** `floatstr` from the CPython encoder, honouring `allow_nan`. */
  _floatstr(value) {
    let text;
    if (Number.isNaN(value)) text = 'NaN';
    else if (value === Infinity) text = 'Infinity';
    else if (value === -Infinity) text = '-Infinity';
    else return floatRepr(value);

    if (!this.allowNan) {
      throw new PyValueError(
        `Out of range float values are not JSON compliant: ${floatRepr(value)}`,
      );
    }
    return text;
  }

  /** Renders a dict key, applying the same coercions CPython does. */
  _keystr(key) {
    if (typeof key === 'string') return key;
    if (key instanceof PyFloat) return this._floatstr(key.value);
    if (key === true) return 'true';
    if (key === false) return 'false';
    if (key === null || key === undefined) return 'null';
    if (typeof key === 'bigint') return intRepr(key);
    if (this.skipkeys) return null;
    throw new PyTypeError(`keys must be str, int, float, bool or None, not object`);
  }

  *_iterencode(o, level, markers) {
    if (typeof o === 'string') {
      yield this.encodeString(o);
    } else if (o === null || o === undefined) {
      yield 'null';
    } else if (o === true) {
      yield 'true';
    } else if (o === false) {
      yield 'false';
    } else if (typeof o === 'bigint') {
      yield intRepr(o);
    } else if (o instanceof PyFloat) {
      yield this._floatstr(o.value);
    } else if (Array.isArray(o)) {
      yield* this._iterencodeList(o, level, markers);
    } else if (o instanceof Map) {
      yield* this._iterencodeDict(o, level, markers);
    } else {
      throw new PyTypeError(`Object of type ${typeof o} is not JSON serializable`);
    }
  }

  *_iterencodeList(lst, level, markers) {
    if (lst.length === 0) {
      yield '[]';
      return;
    }
    if (markers !== null) {
      if (markers.has(lst)) throw new PyValueError('Circular reference detected');
      markers.add(lst);
    }

    let buf = '[';
    let newlineIndent = null;
    let separator = this.itemSeparator;
    if (this.indent !== null) {
      level += 1;
      newlineIndent = '\n' + this.indent.repeat(level);
      separator = this.itemSeparator + newlineIndent;
      buf += newlineIndent;
    }

    let first = true;
    for (const value of lst) {
      if (first) first = false;
      else buf = separator;

      if (typeof value === 'string') {
        yield buf + this.encodeString(value);
      } else if (value === null || value === undefined) {
        yield buf + 'null';
      } else if (value === true) {
        yield buf + 'true';
      } else if (value === false) {
        yield buf + 'false';
      } else if (typeof value === 'bigint') {
        yield buf + intRepr(value);
      } else if (value instanceof PyFloat) {
        yield buf + this._floatstr(value.value);
      } else {
        yield buf;
        if (Array.isArray(value)) {
          yield* this._iterencodeList(value, level, markers);
        } else if (value instanceof Map) {
          yield* this._iterencodeDict(value, level, markers);
        } else {
          yield* this._iterencode(value, level, markers);
        }
      }
    }

    if (newlineIndent !== null) {
      level -= 1;
      yield '\n' + this.indent.repeat(level);
    }
    yield ']';

    if (markers !== null) markers.delete(lst);
  }

  *_iterencodeDict(dct, level, markers) {
    if (dct.size === 0) {
      yield '{}';
      return;
    }
    if (markers !== null) {
      if (markers.has(dct)) throw new PyValueError('Circular reference detected');
      markers.add(dct);
    }

    yield '{';

    let newlineIndent = null;
    let itemSeparator = this.itemSeparator;
    if (this.indent !== null) {
      level += 1;
      newlineIndent = '\n' + this.indent.repeat(level);
      itemSeparator = this.itemSeparator + newlineIndent;
      yield newlineIndent;
    }

    let items = [...dct.entries()];
    if (this.sortKeys) {
      items.sort((x, y) => compareCodePoints(String(x[0]), String(y[0])));
    }

    let first = true;
    for (const [rawKey, value] of items) {
      const key = this._keystr(rawKey);
      if (key === null) continue;

      if (first) first = false;
      else yield itemSeparator;

      yield this.encodeString(key);
      yield this.keySeparator;

      if (typeof value === 'string') {
        yield this.encodeString(value);
      } else if (value === null || value === undefined) {
        yield 'null';
      } else if (value === true) {
        yield 'true';
      } else if (value === false) {
        yield 'false';
      } else if (typeof value === 'bigint') {
        yield intRepr(value);
      } else if (value instanceof PyFloat) {
        yield this._floatstr(value.value);
      } else if (Array.isArray(value)) {
        yield* this._iterencodeList(value, level, markers);
      } else if (value instanceof Map) {
        yield* this._iterencodeDict(value, level, markers);
      } else {
        yield* this._iterencode(value, level, markers);
      }
    }

    if (newlineIndent !== null) {
      level -= 1;
      yield '\n' + this.indent.repeat(level);
    }
    yield '}';

    if (markers !== null) markers.delete(dct);
  }
}

